from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
texts = {
'2.d': 'У ворот адмиралтейства стоят грузчики, матросские жёны и посланцы деревень. Они принесли не японские флаги, а списки пропавших работников и требования прекратить призыв. Представитель портов Хасан согласился войти в зал лишь после обещания выпустить делегацию обратно.\n\n«Вы называете это защитой родины, — начинает он. — Но кто из нас решает, где её границы? Плантатор оставляет себе прибыль, чиновник — должность, а нам достаются могилы». Посланница деревень Сити кладёт на стол долговые расписки: пока мужчины служат, семьи теряют землю.\n\nКасемброот разворачивает карту портов: японский ультиматум касается нефти, каучука и контроля над побережьем. Фабиус просит не путать страх перед вторжением с согласием на колониальные порядки. Сурья Вирата предлагает сначала выслушать тех, кого собираются вооружить. Совет должен выбрать, кто начнёт переговоры.',
'10.d': 'Касемброот придвигает к Хасану карту морских путей. «Закройте эти проливы — и рис не дойдёт до ваших рынков. Отдайте порты Токио — и следующий приказ о погрузке будет написан по-японски. У нас нет месяца на спор о каждом приказе».\n\n«Зато у вас были годы, чтобы услышать наши жалобы», — отвечает Хасан. Он рассказывает о грузчиках, которым задолжали жалованье, и о призывниках, чьи семьи продолжают платить сборы за отсутствующих работников. Сити спрашивает, почему караул охраняет склады компании, когда деревни просят защиты от реквизиций.\n\nАдмирал на миг замолкает. Он признаёт, что снабженцы должны отвечать за воровство, но требует немедленного возвращения людей на службу. Фабиус возражает: приказ заставит человека явиться в казарму, но не удержит его в бою. Делегаты готовы говорить об обороне; принять безусловное повиновение они отказываются.',
'11.d': 'Фабиус начинает не с карты, а с расчётной ведомости. «Здесь одинаковая служба оплачивается по-разному. Если я называю вас товарищами по обороне, эта бумага делает меня лжецом». Он предлагает проверку выплат, помощь семьям и разбор жалоб, сохраняя обязательную службу.\n\nХасан не берёт протянутый документ. «Мой отец уже слышал слово “после”. После урожая, после переписи, после следующей войны. Кто заставит вашего чиновника исполнить обещание?» Сити добавляет: деньги бесполезны, если землевладелец заберёт участок до возвращения солдата.\n\nКасемброот напоминает, что казна не бездонна, а противник не станет ждать окончания проверок. Фабиус отвечает, что сорванный призыв обойдётся дороже. Он предлагает допустить представителей общин к жалобам через совет султанов. Сурья Вирата поддерживает договор, но спрашивает, будет ли у местных солдат право командовать, а не только подчиняться.',
'12.d': 'Сурья Вирата снимает фуражку и садится напротив делегатов. «Я служу на этих кораблях и знаю, как звучит приказ, когда тебя считают чужим. Но японский офицер не вернёт вам землю только потому, что говорит об освобождении». Он предлагает добровольческие части для защиты архипелага.\n\nХасан отвечает, что люди готовы охранять свои причалы, но не хотят быть отправлены за море ради чужих концессий. Сити требует назвать срок службы: деревня не может годами кормить армию и ждать мужчин. Представитель молодых забастовщиков спрашивает, не отнимут ли у добровольцев оружие сразу после того, как исчезнет опасность для администрации.\n\nКасемброот видит другую угрозу: отдельные отряды могут однажды повернуть винтовки против Батавии. «А вы предлагаете дать винтовку человеку, которому заранее не доверяете?» — спрашивает Вирата. Фабиус предлагает обсудить единое снабжение и общий штаб. Впервые спор идёт об условиях совместной защиты, а не о том, кто обязан замолчать.',
'20.d': 'На втором заседании Касемброот требует разоружить пикеты у складов. Хасан отвечает, что без пикетов хозяева снова наймут штрейкбрехеров и забудут долги. «Вы просите доверия, держа людей у ворот под прицелом».\n\nАдмирал говорит о транспортах, которые нельзя разгрузить, и батареях, оставшихся без снарядов. Сити признаёт опасность: семьи портовых рабочих тоже погибнут при высадке. Но она требует отделить защиту гавани от наказания за жалобы. Фабиус предлагает обмен: делегация убеждает людей вернуться, совет рассматривает злоупотребления и условия службы.\n\n«Если я уступлю сейчас, завтра любой приказ будут встречать забастовкой», — говорит Касемброот. «Если не уступите никогда, приказ некому будет выполнять», — отвечает Вирата. Делегация не обещает покорности. Совет может сохранить принуждение, принять договор Фабиуса или доверить защиту добровольцам.',
'21.d': 'Фабиус зачитывает проект договора. Хасан останавливает его на словах о помощи семьям: «Кто получит выплату, если писарь объявит брак недействительным?» Сити требует принимать свидетельства общины. Адмирал соглашается передать спорные случаи на рассмотрение совета султанов.\n\nКасемброот возражает против превращения каждого взыскания в разбирательство. Он опасается, что командиры потеряют власть именно перед вторжением. Фабиус проводит границу: боевой приказ остаётся приказом, спор о невыплаченном жалованье не становится мятежом.\n\nВирата предлагает местных командиров, но Фабиус пока не готов перестраивать всю армию. Хасан признаёт, что договор даст семьям больше защиты, чем прежние обещания, однако молодые делегаты требуют добровольческой службы. Компромисс никого не устраивает полностью. Теперь совет должен решить, достаточно ли этого для общего дела — или выбрать иной порядок.',
'22.d': 'На столе лежит проект добровольческого мандата. Вирата предлагает местных командиров при едином оборонном плане. Касемброот спрашивает прямо: «Если штаб прикажет оставить вашу деревню ради защиты пролива, вы подчинитесь?» Хасан отвечает: «Если вы объясните, что спасаете остров, а не склад компании».\n\nФабиус предупреждает, что армия не может проводить собрание перед каждым манёвром. Делегаты соглашаются на общее командование в бою и единое снабжение. Взамен они требуют письменного ограничения срока службы: после завершения кризиса ополчение должно вернуться домой.\n\nСити просит прочитать эту строку вслух. Касемброот требует именно роспуска частей, опасаясь постоянной вооружённой силы вне старой армии. Вирата принимает условие, хотя часть молодых делегатов считает его уступкой. Договор готов; совет ещё может предпочесть обязательную службу с гарантиями или вернуться к принуждению.',
'30.d': 'Распоряжение о принудительном призыве доставляют в порты раньше утренней смены. Касемброот получает списки вернувшихся людей и говорит, что оборона больше не может ждать. У складов возобновляется погрузка; на перекличке снова слышны ответы.\n\nХасан возвращается к делегатам без подписанного договора. «Мы добились, чтобы нас выслушали. Мы не добились, чтобы нам поверили». Сити уносит долговые расписки: для этих семей заседание ничего не изменило. Фабиус предупреждает совет, что присутствие людей в строю ещё не означает верности.\n\nНекоторые считают жёсткость спасением перед вторжением, другие прячут сыновей и перестают разговаривать с администрацией. Недовольство уходит с площади в деревни. Совет получает возможность опереться на колониальную полицию, но вместе с ней — риск нового партизанского выступления. Спор окончен приказом; его причины остаются.',
'31.d': 'Фабиус подписывает распоряжения о проверке жалованья и защите семей. Хасан ставит подпись под призывом вернуться к работе, но не под благодарностью правительству. «Мы будем судить по первой жалобе, которую вы решите против своего чиновника». Сити просит копию для деревенского собрания.\n\nКасемброот принимает договор ради восстановления службы, предупредив, что требования командования сохраняются. Вирата считает это началом иного разговора, хотя вопрос местных командиров остаётся открытым. Молодые забастовщики уходят недовольными: обязательный призыв не отменён.\n\nВ портах снова работают, а семьи получают обещанные гарантии. Постоянный совет султанов сможет стать путём для дальнейших жалоб, если правительство поддержит его создание. Этот порядок требует средств и ежедневного исполнения. Батавия купила не любовь, а возможность доказать, что её подпись чего-то стоит.',
'32.d': 'На плацу строятся добровольцы. Двенадцать дивизий ополчения получают оружие и место в общем оборонном плане. Вирата обращается к ним без торжественной речи: «За вами остаются дома. Ради них вы здесь». Хасан наблюдает за погрузкой вместе с людьми, которые недавно перекрывали ворота порта.\n\nКасемброот проверяет распоряжения о снабжении. Он по-прежнему опасается самостоятельных частей, но теперь отвечает и за их способность сражаться. Фабиус хранит подписанный мандат; Сити забирает копию с обещанием роспуска после войны.\n\nНе все общины прислали людей. Для одних добровольцы защищают архипелаг, для других помогают прежней администрации пережить кризис. Доверие выросло, но вопрос о власти над островами остался. Когда опасность минует, правительство должно будет выполнить обещание и отпустить тех, кого сегодня вооружает.',
'40.d': 'У причала складывают оружие и сверяют списки. Временный мандат закончился: добровольческие дивизии распущены. Сити встречает возвращающихся людей и ищет знакомые лица; некоторые места в строю навсегда останутся пустыми.\n\n«Армия могла бы пригодиться ещё», — замечает один из штабных офицеров. Фабиус закрывает папку: «Именно поэтому обещание надо выполнить сейчас». Касемброот получает отчёт о роспуске, а Вирата провожает последних добровольцев за ворота.\n\nХасан напоминает, что возвращение винтовок не означает возвращения к молчанию. Люди защищали острова и теперь хотят участвовать в решениях об их будущем. Сегодня Батавия сдержала слово о сроке службы. Ответа на вопрос, кому принадлежит право говорить от имени архипелага, в этом приказе нет.',
'10.a': 'Выслушать ответ делегации.', '11.a': 'Пусть делегаты проверят каждую гарантию.', '12.a': 'Обсудить пределы добровольческой службы.',
'20.a': 'Сохранить принудительный призыв.', '21.a': 'Подписать договор о службе.', '22.a': 'Утвердить добровольческий мандат.',
'30.a': 'Приказ вступает в силу.', '31.a': 'Теперь придётся отвечать за свою подпись.', '32.a': 'Защитим острова вместе.'
}
p = ROOT/'localisation/russian/zzz_borneo_war_l_russian.yml'
s = p.read_text(encoding='utf-8-sig')
for key, value in texts.items():
    line = f' A01_japan.{key}:0 "{value.replace(chr(10), r"\n")}"'
    s, n = re.subn(r'^ A01_japan\.'+re.escape(key)+r':.*$', lambda m: line, s, flags=re.M)
    assert n == 1, key
extra = {'choose_hard':'Вернуться к обязательному призыву без уступок.', 'choose_balance':'Принять гарантии Фабиуса.', 'choose_support':'Доверить оборону добровольцам.'}
for key, value in extra.items():
    if f' A01_japan.{key}:' not in s: s += f' A01_japan.{key}:0 "{value}"\n'
p.write_text(s, encoding='utf-8-sig')
p = ROOT/'localisation/english/zzz_borneo_war_l_english.yml'
s=p.read_text(encoding='utf-8-sig')
for key,value in {'choose_hard':'Return to compulsory service without concessions.', 'choose_balance':'Accept Fabius guarantees.', 'choose_support':'Entrust the defence to volunteers.'}.items():
    if f' A01_japan.{key}:' not in s: s+=f' A01_japan.{key}:0 "{value}"\n'
p.write_text(s,encoding='utf-8-sig')

# At the second sitting the player may change course before the policy is enacted.
p=ROOT/'events/A01_admiral_speeches.txt'
s=p.read_text(encoding='utf-8-sig')
for event, original in [(20,30),(21,31),(22,32)]:
    pattern=r'(^country_event = \{ id = A01_japan\.'+str(event)+r'\b[^\n]*)( \})$'
    current=re.search(pattern,s,re.M)
    if current and 'A01_japan.choose_' in current[0]: continue
    options=''
    for target,key in [(30,'hard'),(31,'balance'),(32,'support')]:
        if target != original:
            options+=f' option = {{ name = A01_japan.choose_{key} ai_chance = {{ factor = 15 }} country_event = {{ id = A01_japan.{target} days = 7 }} }}'
    s,n=re.subn(pattern,lambda m:m[1]+options+m[2],s,flags=re.M)
    assert n==1,event
    s=s.replace(f'name = A01_japan.{event}.a country_event',f'name = A01_japan.{event}.a ai_chance = {{ factor = 70 }} country_event')
p.write_text(s,encoding='utf-8')

# Explicit aliases use vanilla textures already shipped in the mod.
assets = {
'protest':'report_event_worker_protests', 'talks':'report_event_FIN_armistice_of_moscow_negotiations',
'council':'report_event_generic_parliament', 'treaty':'report_event_generic_sign_treaty1',
'navy':'report_event_ast_navy', 'trade':'report_event_merchant_ship_01',
'building':'report_event_generic_construction_site', 'industry':'report_event_generic_factory',
'recruit':'report_event_SWI_enlisting_recruitment', 'unrest':'report_event_india_protests',
}
mapping = {
'A01_japan.1':'talks','A01_japan.2':'protest','A01_japan.4':'unrest','A01_japan.5':'navy',
'A01_japan.10':'council','A01_japan.11':'talks','A01_japan.12':'protest',
'A01_japan.20':'talks','A01_japan.21':'talks','A01_japan.22':'council',
'A01_japan.30':'unrest','A01_japan.31':'treaty','A01_japan.32':'recruit','A01_japan.40':'trade',
'A01_constitution.1':'council','borneo_project.1':'building','southern_war.2':'navy',
'ludolf.10':'council','ludolf.20':'talks','ludolf.21':'treaty','ludolf.30':'building',
'ludolf.31':'treaty','ludolf.32':'recruit','ludolf.33':'council','ludolf.34':'council','ludolf.35':'council','ludolf.36':'council',
}
for i in range(1,7): mapping[f'pacific.{i}']='trade' if i in (1,2,5) else 'talks'
for i in range(1,5): mapping[f'a01_peace_request.{i}']='treaty' if i==3 else 'talks'
for i in range(1,7): mapping[f'sabah_war.{i}']='navy' if i in (1,2,4) else 'talks'
for i in range(1,8): mapping[f'expansion.{i}']='navy' if i in (1,2) else 'talks'
gfx='spriteTypes = {\n'
for key,asset in assets.items():
    assert (ROOT/f'gfx/event_pictures/{asset}.dds').is_file(),asset
    gfx+=f' spriteType = {{ name = "GFX_1896_event_{key}" texturefile = "gfx/event_pictures/{asset}.dds" }}\n'
gfx+='}\n'
(ROOT/'interface/1896_event_pictures.gfx').write_text(gfx,encoding='utf-8')
count=0
for p in (ROOT/'events').glob('*.txt'):
    s=p.read_text(encoding='utf-8-sig')
    # Find complete top-level event blocks without confusing scheduled event calls.
    matches=list(re.finditer(r'(?m)^country_event\s*=\s*\{',s))
    for m in reversed(matches):
        start=m.start(); pos=m.end(); depth=1
        while depth:
            depth+=(s[pos]=='{')-(s[pos]=='}');pos+=1
        block=s[start:pos]
        if not re.search(r'\btitle\s*=',block): continue
        eid=re.search(r'\bid\s*=\s*([\w.]+)',block)[1]
        key=mapping.get(eid,'council')
        picture=f'picture = GFX_1896_event_{key}'
        if re.search(r'\bpicture\s*=',block): block=re.sub(r'\bpicture\s*=\s*\w+',picture,block)
        else: block=re.sub(r'(\bdesc\s*=\s*[\w.]+)',r'\1 '+picture,block,count=1)
        s=s[:start]+block+s[pos:];count+=1
    p.write_text(s,encoding='utf-8')
print(f'Updated illustrations for {count} visible events; expanded 11 narrative descriptions and added six alternative decisions.')
for p in (ROOT/'events').glob('*.txt'):
    s=p.read_text(encoding='utf-8-sig')
    t=re.sub(r'"(?:\\.|[^"\\])*"|#[^\n]*','',s)
    depth=0
    for c in t:
        depth+=(c=='{')-(c=='}')
        assert depth>=0,p
    assert depth==0,p
    for key in re.findall(r'picture = GFX_1896_event_(\w+)',s): assert key in assets,key
print('Verified balanced event scripts, sprite references and texture paths.')
